  <div id="empty-cart" class="rounded-2xl border-2 border-dashed border-slate-200 p-8 text-center text-sm text-slate-500">Selecciona productos arriba para comenzar.</div><div id="cart" class="hidden space-y-3"></div>
  <div class="mt-5 grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(280px,0.7fr)]"><label class="text-sm font-semibold text-slate-700">Notas para el equipo<textarea name="notes" rows="4" class="input-field mt-2" placeholder="Acuerdos, forma de contacto u observaciones…">{{ old('notes') }}</textarea></label><div class="rounded-2xl bg-slate-900 p-5 text-white"><div class="flex justify-between text-sm text-slate-300"><span>Subtotal</span><strong id="reservation-subtotal" class="text-white">C$ 0.00</strong></div><label class="mt-4 block text-sm font-semibold text-slate-200">Anticipo recibido<span class="mt-2 flex overflow-hidden rounded-xl border border-slate-600 bg-white"><span class="flex items-center border-r border-slate-200 bg-slate-100 px-3 font-semibold text-slate-500">C$</span><input id="reservation-deposit" type="number" name="deposit" min="0" step="0.01" value="{{ old('deposit',0) }}" class="min-w-0 flex-1 border-0 bg-white px-3 py-2.5 text-slate-900 outline-none" inputmode="decimal"></span></label><div class="mt-4 flex items-end justify-between border-t border-slate-700 pt-4"><span class="text-sm text-slate-300">Saldo pendiente</span><strong id="reservation-balance" class="text-2xl text-emerald-300">C$ 0.00</strong></div></div></div>
