<script>
document.addEventListener('DOMContentLoaded', () => {
 const cards=[...document.querySelectorAll('.product-card')],grid=document.getElementById('product-grid'),panel=document.getElementById('selection-panel'),cart=document.getElementById('cart'),empty=document.getElementById('empty-cart'),feedback=document.getElementById('product-feedback'),deposit=document.getElementById('reservation-deposit'); let selected=null,rowIndex=0;
 const money=value=>`C$ ${value.toLocaleString('es-NI',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
 const showFeedback=message=>{feedback.textContent=message;feedback.classList.remove('hidden');};
 const resolvePrice=(option,quantity)=>{let price=Number(option?.dataset.basePrice||0);try{JSON.parse(option?.dataset.breaks||'[]').forEach(item=>{if(quantity>=Number(item.min_quantity))price=Number(item.price);});}catch(error){}return price;};
 const recalculate=()=>{let subtotal=0;cart.querySelectorAll('[data-cart-row]').forEach(row=>{const quantity=Number(row.querySelector('[data-qty]').value||0),select=row.querySelector('[data-price-type]'),option=select.selectedOptions[0],price=resolvePrice(option,quantity),lineTotal=quantity*price;option.dataset.price=price;option.textContent=`${option.dataset.label} · ${money(price)}`;subtotal+=lineTotal;row.querySelector('[data-line-unit-price]').textContent=money(price);row.querySelector('[data-line-subtotal]').textContent=money(lineTotal);});const paid=Math.max(0,Number(deposit.value||0));document.getElementById('reservation-subtotal').textContent=money(subtotal);document.getElementById('reservation-balance').textContent=money(Math.max(0,subtotal-paid));deposit.max=subtotal;document.getElementById('save-reservation').disabled=cart.children.length===0||paid>subtotal;};
 document.getElementById('product-search').addEventListener('input',event=>{const term=event.target.value.toLocaleLowerCase().trim();let visible=0;cards.forEach(card=>{const show=card.dataset.search.includes(term);card.classList.toggle('hidden',!show);if(show)visible++;});grid.classList.toggle('hidden',visible===0);document.getElementById('no-products').classList.toggle('hidden',visible!==0);});
 cards.forEach(card=>card.addEventListener('click',()=>{cards.forEach(item=>item.classList.remove('border-indigo-600','bg-indigo-50','ring-2','ring-indigo-200'));card.classList.add('border-indigo-600','bg-indigo-50','ring-2','ring-indigo-200');selected=card.dataset;document.getElementById('selected-name').textContent=selected.name;document.getElementById('selected-meta').textContent=`${selected.code} · ${selected.stock} disponibles · desde ${money(Number(selected.retail))}`;panel.classList.remove('hidden');panel.classList.add('flex');feedback.classList.add('hidden');addRow(selected,1);document.getElementById('qty').value=1;}));
 const addRow=(productData,quantity,priceType='retail')=>{const existing=cart.querySelector(`[data-product-id="${productData.id}"]`);if(existing){const qty=existing.querySelector('[data-qty]'),next=Number(qty.value)+quantity;if(next>Number(productData.stock)){showFeedback(`Solo hay ${productData.stock} unidades disponibles de ${productData.name}.`);return;}qty.value=next;recalculate();return;}const row=document.createElement('article');row.dataset.cartRow='';row.dataset.productId=productData.id;row.className='grid min-w-0 items-end gap-3 rounded-2xl border border-slate-200 p-4 sm:grid-cols-2 xl:grid-cols-[minmax(180px,1fr)_110px_180px_110px_150px_auto]';const identity=document.createElement('div'),title=document.createElement('p'),meta=document.createElement('p'),product=document.createElement('input');identity.className='min-w-0 sm:col-span-2 xl:col-span-1';title.className='truncate font-bold text-slate-900';title.textContent=productData.name;meta.className='text-xs text-slate-500';meta.textContent=`${productData.code} · máximo ${productData.stock}`;product.type='hidden';product.name=`items[${rowIndex}][product_id]`;product.value=productData.id;identity.append(title,meta,product);const qtyLabel=document.createElement('label'),qty=document.createElement('input');qtyLabel.className='text-xs font-semibold text-slate-500';qtyLabel.textContent='Cantidad';qty.type='number';qty.step='0.0001';qty.min='0.0001';qty.max=productData.stock;qty.required=true;qty.value=quantity;qty.name=`items[${rowIndex}][quantity]`;qty.className='input-field mt-1';qty.dataset.qty='';qtyLabel.append(qty);const priceLabel=document.createElement('label'),price=document.createElement('select');priceLabel.className='text-xs font-semibold text-slate-500';priceLabel.textContent='Tipo de precio';price.name=`items[${rowIndex}][price_type]`;price.className='select-field mt-1';price.dataset.priceType='';[['retail','Venta'],['wholesale','Mayorista'],['special','Especial']].forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=`${label} · ${money(Number(productData[value]))}`;option.dataset.label=label;option.dataset.basePrice=productData[value];option.dataset.breaks=productData[`${value}Breaks`]||'[]';option.selected=value===priceType;price.append(option);});priceLabel.append(price);const unit=document.createElement('div'),unitLabel=document.createElement('span'),unitValue=document.createElement('strong');unit.className='rounded-xl bg-slate-50 px-3 py-2';unitLabel.className='block text-xs text-slate-500';unitLabel.textContent='Precio unitario';unitValue.className='block text-sm text-slate-800';unitValue.dataset.lineUnitPrice='';unit.append(unitLabel,unitValue);const subtotal=document.createElement('div'),subtotalLabel=document.createElement('span'),subtotalValue=document.createElement('strong');subtotal.className='rounded-xl bg-indigo-50 px-3 py-2';subtotalLabel.className='block text-xs text-indigo-500';subtotalLabel.textContent='Subtotal';subtotalValue.className='block text-base text-indigo-800';subtotalValue.dataset.lineSubtotal='';subtotal.append(subtotalLabel,subtotalValue);const remove=document.createElement('button');remove.type='button';remove.className='rounded-xl px-3 py-2 text-sm font-semibold text-red-600 hover:bg-red-50';remove.textContent='Quitar';remove.addEventListener('click',()=>{row.remove();empty.classList.toggle('hidden',cart.children.length>0);cart.classList.toggle('hidden',cart.children.length===0);recalculate();});qty.addEventListener('input',recalculate);price.addEventListener('change',recalculate);row.append(identity,qtyLabel,priceLabel,unit,subtotal,remove);cart.append(row);rowIndex++;empty.classList.add('hidden');cart.classList.remove('hidden');feedback.classList.add('hidden');recalculate();};
 document.getElementById('add-product').addEventListener('click',()=>{const quantity=Number(document.getElementById('qty').value);if(!selected){showFeedback('Primero selecciona un producto.');return;}if(quantity<=0){showFeedback('Ingresa una cantidad válida.');return;}if(quantity>Number(selected.stock)){showFeedback(`Solo hay ${selected.stock} unidades disponibles.`);return;}addRow(selected,quantity);});
 document.getElementById('reservation-warehouse').addEventListener('change',event=>{if(cart.children.length){cart.replaceChildren();empty.classList.remove('hidden');cart.classList.add('hidden');showFeedback('La bodega cambió; vuelve a seleccionar los productos según sus nuevas existencias.');}cards.forEach(card=>{let stock={physical:0,reserved:0,available:0};try{stock=JSON.parse(card.dataset.stockMap||'{}')[event.target.value]||stock;}catch(error){}card.dataset.stock=stock.available;card.querySelector('[data-physical-stock]').textContent=stock.physical;card.querySelector('[data-reserved-stock]').textContent=stock.reserved;card.querySelector('[data-available-stock]').textContent=stock.available;card.querySelector('[data-stock-badge]').textContent=`${stock.available} disp.`;card.disabled=Number(stock.available)<=0;card.classList.toggle('opacity-50',card.disabled);});selected=null;panel.classList.add('hidden');panel.classList.remove('flex');recalculate();});
 deposit.addEventListener('input',recalculate);
 document.querySelector('form').addEventListener('submit',event=>{if(cart.children.length===0){event.preventDefault();showFeedback('Agrega al menos un producto antes de guardar.');document.getElementById('product-search').focus();}else if(Number(deposit.value||0)>Number(deposit.max||0)){event.preventDefault();showFeedback('El anticipo no puede superar el subtotal del apartado.');deposit.focus();}});
 document.getElementById('reservation-warehouse').dispatchEvent(new Event('change'));
 @foreach(old('items', []) as $oldItem)
  { const card=cards.find(item=>item.dataset.id===@json((string) ($oldItem['product_id'] ?? ''))); if(card)addRow(card.dataset,Number(@json($oldItem['quantity'] ?? 1)),@json($oldItem['price_type'] ?? 'retail')); }
 @endforeach
 @if(empty(old('items', [])))
  try {
   const draft=JSON.parse(sessionStorage.getItem('estelipos.reservationDraft')||'null');
   (draft?.items||[]).forEach(item=>{const card=cards.find(candidate=>candidate.dataset.id===String(item.product_id));if(card&&Number(card.dataset.stock)>=Number(item.quantity))addRow(card.dataset,Number(item.quantity),item.price_type||'retail');});
   if(draft)sessionStorage.removeItem('estelipos.reservationDraft');
  } catch(error) { sessionStorage.removeItem('estelipos.reservationDraft'); }
 @endif
 recalculate();
});
</script>
@endsection
